    public function stream_write($d) { return strlen($d); }
    public function stream_eof() { return $this->pos >= 100; }
    public function stream_tell() { return $this->pos; }
    public function stream_seek($o, $w) { return false; }
    public function stream_stat() { return []; }
    public function stream_close() {}
}
stream_wrapper_register("chunkr2", "R");
// bounded, stopping BEFORE the end
$h = fopen("chunkr2://x", "rb"); stream_set_chunk_size($h, 17);
$s = stream_get_contents($h, 30); fclose($h);
printf("bounded-30 len=%d reads=%s\\n", strlen($s), implode(",", R::$reads));
// bounded PAST the end
R::$reads = [];
$h = fopen("chunkr2://x", "rb"); stream_set_chunk_size($h, 17);
$s = stream_get_contents($h, 500); fclose($h);
printf("bounded-500 len=%d reads=%s\\n", strlen($s), implode(",", R::$reads));
// unbounded with the fgets reader instead
R::$reads = [];
$h = fopen("chunkr2://x", "rb"); stream_set_chunk_size($h, 17);
$n = 0; while (($l = fgets($h)) !== false) { $n += strlen($l); } fclose($h);
printf("fgets len=%d reads=%d\\n", $n, count(R::$reads));
